"""Versioned, reviewable questions. Correct option is first before server-side shuffling.
These items establish a working blueprint, not an empirically validated psychometric scale.
"""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
BANK=[]
def add(spec,competency,prompt,options,explanation,level=0):
    BANK.append(dict(specialization=spec,competency=competency,prompt=prompt,options=options,correct=0,explanation=explanation,difficulty=level))
def group(spec,questions):
    for i,(competency,prompt,options,explanation) in enumerate(questions):add(spec,competency,prompt,options,explanation,0 if i<4 else 2)

